  "Correct answer": {"de":"Richtige Antwort","es":"Respuesta correcta","fr":"Bonne réponse","it":"Risposta corretta","pt":"Resposta correta","nl":"Juist antwoord","sv":"Rätt svar","no":"Riktig svar","da":"Rigtigt svar","fi":"Oikea vastaus","sq":"Përgjigje e saktë","bg":"Верен отговор","bs":"Tačan odgovor","hr":"Točan odgovor","mk":"Точен одговор","ro":"Răspuns corect","sr":"Тачан одговор","sl":"Pravilen odgovor","pl":"Poprawna odpowiedź","cs":"Správná odpověď","tr":"Doğru cevap","uk":"Правильна відповідь","kk":"Дұрыс жауап","az":"Düzgün cavab","uz":"Toʻgʻri javob","tg":"Ҷавоби дуруст","fa":"پاسخ درست","ar":"الإجابة الصحيحة","vi":"Đáp án đúng","zh":"正确答案","ja":"正解","ko":"정답"},
  "Correct answer is highlighted": {"pt":"Resposta correta está destacada","fr":"La bonne réponse est surlignée","no":"Riktig svar er markert","nl":"Goed antwoord is gemarkeerd","it":"La risposta corretta è evidenziata","de":"Die richtige Antwort ist markiert","sv":"Rätt svar är markerat","es":"La respuesta correcta está resaltada","bg":"Правилният отговор е отбелязан","fi":"Oikea vastaus on korostettu","da":"Korrekt svar er markeret","hr":"Točan odgovor je označen","sq":"Përgjigjja e saktë është theksuar"},
  "Correct answer was not recorded for this older item.": {"pt":"A resposta correta não foi registrada para esse item antigo.","fr":"La bonne réponse n'a pas été enregistrée pour cet ancien élément.","no":"Riktig svar ble ikke lagret for dette eldre elementet.","nl":"Het juiste antwoord is niet opgeslagen voor dit oudere item.","it":"La risposta corretta non è stata registrata per questa voce precedente.","de":"Die richtige Antwort wurde für diesen älteren Eintrag nicht gespeichert.","sv":"Rätt svar sparades inte för det här äldre objektet.","es":"No se registró la respuesta correcta para este elemento antiguo.","bg":"Правилният отговор не е записан за тази по-стара задача.","fi":"Oikeaa vastausta ei tallennettu tälle vanhemmalle kohteelle.","da":"Korrekt svar blev ikke gemt for denne ældre post.","hr":"Točan odgovor nije zabilježen za ovu stariju stavku.","sq":"Përgjigjja e saktë nuk u regjistrua për këtë element të vjetër."},
  "Correct answer: ": {"pt":"Resposta correta:","fr":"Bonne réponse :","it":"Risposta corretta:","de":"Richtige Antwort:","nl":"Goed antwoord:","no":"Riktig svar:","sv":"Rätt svar:","es":"Respuesta correcta:","da":"Korrekt svar:","fi":"Oikea vastaus:","bg":"Правилен отговор:","hr":"Točan odgovor:","sq":"Përgjigjja e saktë:","mk":"Точен одговор:","ro":"Răspuns corect:","bs":"Tačan odgovor:","sr":"Тачан одговор:"},
  "Correct — moved to the next review step.": {"pt":"Correto — passou para o próximo passo da revisão.","fr":"Correct — passage à l'étape suivante.","nl":"Goed — doorgeschoven naar de volgende herhaling.","no":"Riktig — flyttet til neste repetisjon.","de":"Richtig — zur nächsten Wiederholung verschoben.","it":"Corretto — passato al prossimo step di ripasso.","sv":"Rätt — flyttad till nästa repetitionssteg.","es":"Correcto — pasa al siguiente paso de repaso.","bg":"Вярно — задачата е преместена на следващата стъпка за повторение.","fi":"Oikein — siirretty seuraavaan kertausvaiheeseen.","da":"Rigtigt — flyttet til næste repetitionsrunde.","hr":"Točno — zadatak je prebačen na sljedeći korak ponavljanja."},
  "Correct — you heard it accurately.": {"pt":"Correto — você ouviu corretamente.","fr":"Correct — tu as bien compris la phrase.","it":"Corretto — hai riconosciuto la frase esattamente.","no":"Riktig — du oppfattet det riktig.","de":"Richtig – du hast es genau verstanden.","nl":"Goed — je hebt het precies verstaan.","es":"Correcto: lo escuchaste bien.","sv":"Rätt — du hörde det korrekt.","fi":"Oikein — kuulit sen oikein.","da":"Korrekt — du hørte det rigtigt.","bg":"Вярно — чу го точно.","hr":"Točno — točno si prepoznao/la frazu.","sq":"Saktë — e dëgjove saktësisht.","mk":"Точно — точно ја препозна фразата."},
  "Correct!": {"de":"Richtig!","es":"¡Correcto!","fr":"Correct !","it":"Corretto!","pt":"Correto!","nl":"Goed!","sv":"Rätt!","no":"Riktig!","da":"Rigtigt!","fi":"Oikein!","sq":"Saktë!","bg":"Вярно!","bs":"Tačno!","hr":"Točno!","mk":"Точно!","ro":"Corect!","sr":"Тачно!","sl":"Pravilno!","pl":"Poprawnie!","cs":"Správně!","tr":"Doğru!","uk":"Правильно!","kk":"Дұрыс!","az":"Düzgün!","uz":"Toʻgʻri!","tg":"Дуруст!","fa":"درست!","ar":"صحيح!","vi":"Đúng!","zh":"正确！","ja":"正解！","ko":"정답!"},
