  "TEACHING PROFILE": {"pt":"PERFIL DO PROFESSOR","it":"PROFILO INSEGNANTE","no":"LÆRERPROFIL","nl":"DOCENTENPROFIEL","de":"LEHRPROFIL","fr":"PROFIL ENSEIGNANT","es":"PERFIL DE ENSEÑANZA","sv":"LÄRARPROFIL","da":"UNDERVISNINGSPROFIL","fi":"OPETTAJAN PROFIILI","bg":"ПРОФИЛ НА ПРЕПОДАВАТЕЛЯ","hr":"PROFIL UČITELJA","sq":"PROFILI I MËSUESIT","bs":"PROFIL PREDAVAČA","mk":"ПРОФИЛ НА НАСТАВНИК","ro":"PROFIL PROFESOR"},
