  "Your library": {"pt":"Sua biblioteca","it":"La tua libreria","de":"Deine Bibliothek","no":"Ditt bibliotek","nl":"Je bibliotheek","fr":"Ta bibliothèque","es":"Tu biblioteca","sv":"Ditt bibliotek","da":"Dit bibliotek","fi":"Kirjastosi","bg":"Твоята библиотека","sq":"Biblioteka jote","hr":"Tvoja biblioteka","bs":"Tvoja biblioteka","mk":"Твоја библиотека","ro":"Biblioteca ta","sl":"Tvoja knjižnica"},
